async function main(req) {
  const urls = env('HEALTH_CHECK_URLS', 'https://example.com').split(',');
  const results = [];

  for (const url of urls) {
    const trimmed = url.trim();
    const start = Date.now();
    try {
      const resp = await fetch(trimmed);
      results.push({
        url: trimmed,
        status: resp.status,
        ok: resp.ok,
        latency_ms: Date.now() - start
      });
    } catch (err) {
      results.push({
        url: trimmed,
        status: 0,
        ok: false,
        error: err.message,
        latency_ms: Date.now() - start
      });
    }
  }

  const failures = results.filter(r => !r.ok);
  const summary = {
    checked_at: new Date().toISOString(),
    total: results.length,
    healthy: results.length - failures.length,
    unhealthy: failures.length,
    results
  };

  // Alert on failures
  if (failures.length > 0) {
    log('ALERT: unhealthy services detected:', JSON.stringify(failures));
    const slackUrl = env('SLACK_WEBHOOK_URL');
    if (slackUrl) {
      const msg = `🚨 ${failures.length} service(s) down: ${failures.map(f => f.url).join(', ')}`;
      try {
        await fetch(slackUrl, {
          method: 'POST',
          body: JSON.stringify({ text: msg }),
          headers: { 'Content-Type': 'application/json' }
        });
      } catch (_) {}
    }
  }

  return summary;
}
